<?php $report=$_GET['report']??'inventory';$from=$_GET['from']??'';$to=$_GET['to']??'';$cat=(int)($_GET['category']??0);$cats=$pdo->query('SELECT id,name FROM equipment_categories ORDER BY name')->fetchAll();$datasets=['inventory'=>['title'=>'Equipment inventory','sql'=>'SELECT e.name equipment,c.name category,i.asset_code,i.condition_label,i.status FROM equipment_items i JOIN equipment e ON e.id=i.equipment_id JOIN equipment_categories c ON c.id=e.category_id WHERE (?=0 OR c.id=?) ORDER BY c.name,e.name','args'=>[$cat,$cat],'heads'=>['Equipment','Category','Asset ID','Condition','Status']],'availability'=>['title'=>'Equipment availability','sql'=>"SELECT c.name category,COUNT(i.id) total,SUM(i.status='Available') available,SUM(i.status='On Loan') on_loan,SUM(i.status='Awaiting Inspection') inspection,SUM(i.status='Under Repair') repair FROM equipment_categories c LEFT JOIN equipment e ON e.category_id=c.id LEFT JOIN equipment_items i ON i.equipment_id=e.id GROUP BY c.id ORDER BY c.name",'args'=>[],'heads'=>['Category','Total','Available','On loan','Awaiting inspection','Under repair']],'active'=>['title'=>'Active loans','sql'=>"SELECT b.full_name borrower,e.name equipment,i.asset_code,l.issued_at,l.due_date FROM loans l JOIN borrowers b ON b.id=l.borrower_id JOIN equipment_items i ON i.id=l.item_id JOIN equipment e ON e.id=i.equipment_id WHERE l.returned_at IS NULL AND (?='' OR l.issued_at>=?) AND (?='' OR l.issued_at<=?) ORDER BY l.due_date",'args'=>[$from,$from,$to,$to],'heads'=>['Borrower','Equipment','Asset ID','Issued','Due']],'overdue'=>['title'=>'Overdue loans','sql'=>"SELECT b.full_name borrower,e.name equipment,i.asset_code,l.issued_at,l.due_date,DATEDIFF(CURDATE(),l.due_date) days_overdue FROM loans l JOIN borrowers b ON b.id=l.borrower_id JOIN equipment_items i ON i.id=l.item_id JOIN equipment e ON e.id=i.equipment_id WHERE l.returned_at IS NULL AND l.due_date<CURDATE() AND (?='' OR l.due_date>=?) AND (?='' OR l.due_date<=?) ORDER BY l.due_date",'args'=>[$from,$from,$to,$to],'heads'=>['Borrower','Equipment','Asset ID','Issued','Due','Days overdue']],'history'=>['title'=>'Loan history','sql'=>"SELECT b.full_name borrower,e.name equipment,i.asset_code,l.issued_at,l.due_date,l.returned_at,l.return_condition FROM loans l JOIN borrowers b ON b.id=l.borrower_id JOIN equipment_items i ON i.id=l.item_id JOIN equipment e ON e.id=i.equipment_id WHERE (?='' OR l.issued_at>=?) AND (?='' OR l.issued_at<=?) ORDER BY l.issued_at DESC",'args'=>[$from,$from,$to,$to],'heads'=>['Borrower','Equipment','Asset ID','Issued','Due','Returned','Return condition']],'condition'=>['title'=>'Equipment condition','sql'=>'SELECT e.name equipment,c.name category,i.asset_code,i.condition_label,i.status FROM equipment_items i JOIN equipment e ON e.id=i.equipment_id JOIN equipment_categories c ON c.id=e.category_id ORDER BY i.condition_label,c.name','args'=>[],'heads'=>['Equipment','Category','Asset ID','Condition','Status']]];if(!isset($datasets[$report]))$report='inventory';$d=$datasets[$report];$s=$pdo->prepare($d['sql']);$s->execute($d['args']);$rows=$s->fetchAll();layout_start('Reports','reports'); ?><div class="page-heading"><div><p class="eyebrow">OPERATIONS</p><h1>Reports</h1><p class="muted">Use current records to understand inventory and lending.</p></div></div><section class="panel"><form method="get" class="filter-bar report-filters"><input type="hidden" name="page" value="reports"><label>Report<select name="report"><?php foreach($datasets as $key=>$one): ?><option value="<?=$key?>" <?=$report===$key?'selected':''?>><?=h($one['title'])?></option><?php endforeach; ?></select></label><?php if(in_array($report,['inventory','condition'],true)): ?><label>Category<select name="category"><option value="0">All categories</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach; ?></select></label><?php endif; ?><?php if(in_array($report,['active','overdue','history'],true)): ?><label>From<input type="date" name="from" value="<?=h($from)?>"></label><label>To<input type="date" name="to" value="<?=h($to)?>"></label><?php endif; ?><button class="button secondary">Run report</button><a class="button primary" href="?page=export&report=<?=h($report)?>&from=<?=h($from)?>&to=<?=h($to)?>&category=<?=$cat?>">↓ Export CSV</a></form><div class="panel-heading"><div><h2><?=h($d['title'])?></h2><p class="muted"><?=count($rows)?> records</p></div></div><div class="table-scroll"><table><thead><tr><?php foreach($d['heads'] as $head): ?><th><?=h($head)?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($row as $value): ?><td><?=h($value??'—')?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="table-empty">No records match this report.</div><?php endif; ?></div></section><?php layout_end();
